import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("SBIN.NS"); // Default to SBI
  const [loading, setLoading] = useState(false);

  // Full Stock List with SBI and Paytm Corrected
  const stockList = [
    { name: "SBI (State Bank of India)", symbol: "SBIN.NS" },
    { name: "Paytm (One97)", symbol: "PAYTM.NS" },
    { name: "Reliance Industries", symbol: "RELIANCE.NS" },
    { name: "Tata Motors", symbol: "TATAMOTORS.NS" },
    { name: "Adani Enterprises", symbol: "ADANIENT.NS" },
    { name: "TCS", symbol: "TCS.NS" },
    { name: "HDFC Bank", symbol: "HDFCBANK.NS" },
    { name: "Infosys", symbol: "INFY.NS" },
    { name: "Zomato", symbol: "ZOMATO.NS" }
  ];

  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        setData(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Backend Error:", err);
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData(selectedStock);
  }, [selectedStock]);

  return (
    <div style={{ backgroundColor: '#0e1117', color: '#c9d1d9', minHeight: '100vh', padding: '20px', fontFamily: 'monospace' }}>
      
      {/* Header */}
      <div style={{ borderBottom: '1px solid #30363d', paddingBottom: '10px', marginBottom: '20px', display: 'flex', justifyContent: 'space-between' }}>
        <h2 style={{ color: '#58a6ff', margin: 0 }}>🛡️ QuantShield AI Dashboard</h2>
        <button onClick={() => fetchData(selectedStock)} style={{ background: '#238636', color: 'white', border: 'none', padding: '5px 15px', borderRadius: '5px', cursor: 'pointer' }}>🔄 REFRESH LIVE</button>
      </div>

      {/* Stock Selection */}
      <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d', marginBottom: '20px' }}>
        <label style={{ marginRight: '15px', fontWeight: 'bold' }}>📁 PORTFOLIO ASSET:</label>
        <select 
          value={selectedStock} 
          onChange={(e) => setSelectedStock(e.target.value)}
          style={{ background: '#0d1117', color: 'white', border: '1px solid #58a6ff', padding: '10px', borderRadius: '5px', width: '350px', fontSize: '16px' }}
        >
          {stockList.map(s => <option key={s.symbol} value={s.symbol}>{s.name}</option>)}
        </select>
        {loading && <span style={{marginLeft: '15px', color: '#f1e05a'}}>⚡ Analyzing...</span>}
      </div>

      {data && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.5fr', gap: '20px' }}>
          
          {/* Left Panel: Real-Time Market Metrics */}
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            <h3 style={{ color: '#ff4b4b' }}>📊 Risk Analysis</h3>
            
            {/* Live Price Highlight Box */}
            <div style={{ background: '#0d1117', padding: '15px', borderRadius: '10px', border: '1px solid #58a6ff', marginBottom: '20px', textAlign: 'center' }}>
              <span style={{ color: '#8b949e', fontSize: '12px' }}>CURRENT MARKET PRICE</span>
              <h1 style={{ color: '#58a6ff', margin: '5px 0', fontSize: '2.5rem' }}>₹{data.current_price}</h1>
            </div>

            <div style={{ lineHeight: '3', fontSize: '18px' }}>
              <div style={{ borderBottom: '1px solid #21262d' }}>Volatility Index: <b style={{float: 'right', color: '#f85149'}}>{data.volatility}</b></div>
              <div style={{ borderBottom: '1px solid #21262d' }}>Market Regime: <b style={{float: 'right'}}>{data.regime}</b></div>
              <div style={{ borderBottom: '1px solid #21262d' }}>BSI (Momentum): <b style={{float: 'right', color: '#d2a8ff'}}>{data.bsi_score}</b></div>
            </div>

            <div style={{ 
              marginTop: '40px', padding: '15px', textAlign: 'center', borderRadius: '8px',
              background: data.regime === "STRESS" ? '#4a151b' : '#064e3b',
              border: `2px solid ${data.regime === "STRESS" ? '#f85149' : '#238636'}`,
              color: 'white', fontWeight: 'bold'
            }}>
              🛡️ GHOST HEDGE: {data.regime === "STRESS" ? "ACTIVE" : "INACTIVE"}
            </div>
          </div>

          {/* Right Panel: AI Predictions & Simulation */}
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            
            {/* Prediction Box */}
            <div style={{ background: '#0d1117', padding: '15px', borderRadius: '10px', border: '1px solid #30363d', marginBottom: '20px' }}>
              <h4 style={{ color: '#f1e05a', marginTop: 0 }}>🔮 2-DAY AI FORECAST</h4>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <p style={{ margin: '5px 0' }}>Day 1 Prediction: <b>₹{data.prediction?.day1}</b></p>
                  <p style={{ margin: '5px 0' }}>Day 2 Prediction: <b>₹{data.prediction?.day2}</b></p>
                </div>
                <div style={{ textAlign: 'center', padding: '10px 20px', background: data.prediction?.trend === "UP" ? '#238636' : '#f85149', borderRadius: '5px' }}>
                  <span style={{ fontSize: '10px' }}>TREND</span>
                  <h3 style={{ margin: 0 }}>{data.prediction?.trend} ({data.prediction?.pct})</h3>
                </div>
              </div>
            </div>

            <h3 style={{ color: '#58a6ff' }}>🎲 Portfolio Simulation (₹10,000)</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
              <div style={{ background: '#0d1117', padding: '15px', borderRadius: '10px', borderLeft: '5px solid #238636' }}>
                <p style={{ margin: 0, fontSize: '12px' }}>Expected Value</p>
                <h2 style={{ color: '#3fb950' }}>₹{data.forecast?.expected}</h2>
              </div>
              <div style={{ background: '#0d1117', padding: '15px', borderRadius: '10px', borderLeft: '5px solid #f85149' }}>
                <p style={{ margin: 0, fontSize: '12px' }}>Worst Case</p>
                <h2 style={{ color: '#f85149' }}>₹{data.forecast?.worst_case}</h2>
              </div>
            </div>

            <div style={{ 
              marginTop: '30px', padding: '20px', textAlign: 'center', borderRadius: '10px', 
              background: data.decision === "BUY" ? '#238636' : data.decision === "AVOID" ? '#f85149' : '#f1e05a',
              color: data.decision === "HOLD" ? 'black' : 'white',
              fontSize: '28px', fontWeight: 'extrabold'
            }}>
              🤖 AI VERDICT: {data.decision}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
